using System.Globalization;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Data;
using System.Windows.Media.Animation;
using SysAdminAssistant.Core;
using SysAdminAssistant.Infrastructure;
namespace SysAdminAssistant.Desktop;
public partial class MainWindow
{
 private static string UpdateDetails(OsUpdateStatus u)=>"Состояние: "+(u.State=="Available"?"Есть обновления":u.State=="Current"?"По последней проверке обновлений нет":"Нет подтверждённых данных")+"\nУстановлено: "+u.Installed+"\nДоступно: "+u.Available+"\nПроверено: "+(u.CheckedUtc?.ToServerTime().ToString("dd.MM.yyyy HH:mm")??"неизвестно")+(u.Stale?" · сведения устарели":"")+(u.RebootRequired?"\nТребуется перезагрузка":"")+"\n"+u.Detail+"\n"+string.Join("\n",u.Items)+(u.PendingCount>u.Items.Length?"\nВсего обновлений: "+u.PendingCount:"")+"\nЧто сделать: проверьте список обновлений на самом устройстве, совместимость и резервную копию; установку и перезагрузку запланируй в окно обслуживания. Сведения из письма подтверждаются вручную кнопкой «Обновление установлено»; устаревший кэш требует проверки на узле. Assistant не устанавливает обновления ОС.";
 private DataGridColumn UpdatesColumn(){var button=new FrameworkElementFactory(typeof(TextBlock));button.SetValue(FrameworkElement.StyleProperty,null);button.SetBinding(TextBlock.TextProperty,new Binding("Updates"){Converter=new UpdateIconConverter(),NotifyOnTargetUpdated=true});button.SetBinding(FrameworkElement.ToolTipProperty,new Binding("Updates"){Converter=new UpdateTipConverter()});button.SetBinding(UIElement.VisibilityProperty,new Binding("Updates"){Converter=new UpdateVisibilityConverter()});button.SetValue(TextBlock.FontFamilyProperty,new System.Windows.Media.FontFamily("Segoe UI Symbol"));button.SetValue(TextBlock.FontSizeProperty,20d);button.SetValue(TextBlock.PaddingProperty,new Thickness(4));button.SetValue(FrameworkElement.HorizontalAlignmentProperty,HorizontalAlignment.Center);button.SetValue(FrameworkElement.VerticalAlignmentProperty,VerticalAlignment.Center);button.SetValue(FrameworkElement.CursorProperty,System.Windows.Input.Cursors.Hand);button.SetValue(UIElement.FocusableProperty,true);button.SetValue(FrameworkElement.FocusVisualStyleProperty,null);button.SetValue(System.Windows.Automation.AutomationProperties.NameProperty,"Обновления устройства");
 button.AddHandler(UIElement.MouseLeftButtonUpEvent,new System.Windows.Input.MouseButtonEventHandler(async(sender,e)=>{e.Handled=true;var b=(FrameworkElement)sender;if(b.DataContext==null)return;var u=b.DataContext.GetType().GetProperty("Updates")?.GetValue(b.DataContext) as OsUpdateStatus;if(u==null)return;var owner=Window.GetWindow(b)??this;try{var entity=b.DataContext.GetType().GetProperty("Entity")?.GetValue(b.DataContext);if(entity is Device d)await ShowDeviceUpdates(d.Id,d.OsUpdatesJson==""?null:OsUpdateStatus.Parse(d.OsUpdatesJson),owner,AccessRules.Level(remote.CurrentUser,NetworkDevices.Module(d.Type))>=2);else if(entity is RouterMonitorRow router&&router.Id!=null)await ShowDeviceUpdates(router.Id.Value,router.Updates,owner,AccessRules.Level(remote.CurrentUser,"routers")>=2);else if(b.DataContext is RouterMonitorRow row&&row.Id!=null)await ShowDeviceUpdates(row.Id.Value,row.Updates,owner,AccessRules.Level(remote.CurrentUser,"routers")>=2);else new FormDialog(owner,"Обновления ОС").Note(UpdateDetails(u)).ViewOnly().ShowDialog();}catch(Exception error){AppMessageBox.Show(owner,error.Message,"Обновления",MessageBoxButton.OK,MessageBoxImage.Error);}}));
 button.AddHandler(UIElement.KeyDownEvent,new System.Windows.Input.KeyEventHandler((sender,e)=>{if(e.Key is System.Windows.Input.Key.Enter or System.Windows.Input.Key.Space){e.Handled=true;((FrameworkElement)sender).RaiseEvent(new System.Windows.Input.MouseButtonEventArgs(System.Windows.Input.Mouse.PrimaryDevice,Environment.TickCount,System.Windows.Input.MouseButton.Left){RoutedEvent=UIElement.MouseLeftButtonUpEvent});}}));
 button.AddHandler(Binding.TargetUpdatedEvent,new EventHandler<DataTransferEventArgs>((sender,e)=>{if(sender is not FrameworkElement b)return;var u=b.DataContext?.GetType().GetProperty("Updates")?.GetValue(b.DataContext) as OsUpdateStatus;b.BeginAnimation(UIElement.OpacityProperty,null);if(u?.HasUpdates==true&&SystemParameters.ClientAreaAnimation)b.BeginAnimation(UIElement.OpacityProperty,new DoubleAnimation(.5,1,TimeSpan.FromSeconds(1.5)){AutoReverse=true,RepeatBehavior=RepeatBehavior.Forever});}));
 button.AddHandler(FrameworkElement.LoadedEvent,new RoutedEventHandler((sender,e)=>{var b=(FrameworkElement)sender;var u=b.DataContext?.GetType().GetProperty("Updates")?.GetValue(b.DataContext) as OsUpdateStatus;if(u?.HasUpdates==true&&SystemParameters.ClientAreaAnimation)b.BeginAnimation(UIElement.OpacityProperty,new DoubleAnimation(.5,1,TimeSpan.FromSeconds(1.5)){AutoReverse=true,RepeatBehavior=RepeatBehavior.Forever});}));button.AddHandler(FrameworkElement.UnloadedEvent,new RoutedEventHandler((sender,e)=>((FrameworkElement)sender).BeginAnimation(UIElement.OpacityProperty,null)));
 var cellStyle=new Style(typeof(DataGridCell));cellStyle.Setters.Add(new Setter(Control.BorderThicknessProperty,new Thickness(0)));cellStyle.Setters.Add(new Setter(Control.BackgroundProperty,System.Windows.Media.Brushes.Transparent));cellStyle.Setters.Add(new Setter(FrameworkElement.FocusVisualStyleProperty,null));var cellTemplate=new ControlTemplate(typeof(DataGridCell));cellTemplate.VisualTree=new FrameworkElementFactory(typeof(ContentPresenter));cellStyle.Setters.Add(new Setter(Control.TemplateProperty,cellTemplate));
 return new DataGridTemplateColumn{Header="ОС",Width=42,CellStyle=cellStyle,CellTemplate=new DataTemplate{VisualTree=button},CanUserSort=false};}
}
public sealed class UpdateIconConverter:IValueConverter{public object Convert(object value,Type t,object p,CultureInfo c)=>value is OsUpdateStatus u?u.HasUpdates?"↻":u.State=="Unknown"||u.Stale?"?":"":"";public object ConvertBack(object v,Type t,object p,CultureInfo c)=>throw new NotSupportedException();}
public sealed class UpdateTipConverter:IValueConverter{public object Convert(object value,Type t,object p,CultureInfo c)=>value is OsUpdateStatus u?(u.HasUpdates?"Есть обновления ОС":"Обновления ОС")+(u.Detail.StartsWith("Есть уведомления об обновлениях по почте")?" · сведения из писем":u.Stale?" · данные устарели":"")+" · нажмите для подробностей":"";public object ConvertBack(object v,Type t,object p,CultureInfo c)=>throw new NotSupportedException();}

public sealed class UpdateVisibilityConverter:IValueConverter{public object Convert(object v,Type t,object p,CultureInfo c)=>v is OsUpdateStatus u&&(u.HasUpdates||u.Stale||u.State=="Unknown")?Visibility.Visible:Visibility.Collapsed;public object ConvertBack(object v,Type t,object p,CultureInfo c)=>throw new NotSupportedException();}
